"""CPU map agent: full replay lifecycle with atomic capacity and versions.

State is per job.  Every operation validates all preconditions and capacities
before mutating anything, so a rejection changes nothing at all.
"""

import struct

from compiler.compiler import compile_image, DENY
from syntax import parse_policy, PolicyError

U32 = 4294967295
REJECTED = {'error': 'rejected'}
OK = {'ok': True}


def _hex_valid(wire):
    if len(wire) != 48:
        return None
    try:
        return bytes.fromhex(wire)
    except ValueError:
        return None


class Agent:
    def __init__(self, services, limits):
        self.name_to_label = {s['name']: s['label'] for s in services}
        labels = sorted(self.name_to_label.values())
        self.label_to_col = {lab: i for i, lab in enumerate(labels)}
        self.ncols = len(labels)
        self.limits = limits

        self.images = {}          # epoch -> {'accept','rows','cells','refs'}
        self.active = None
        self.stage_hw = 0
        self.cells_total = 0

        self.units = {}           # (ns,pid) -> {'gen','service','mark','ctx'}
        self.unit_hw = {}         # (ns,pid) -> last spawn/clone generation
        self.connections = {}     # (id,gen) -> {'mark','pk'}
        self.conn_hw = {}         # id -> last open generation
        self.files = {}           # id -> {'gen','epoch','state'}
        self.file_hw = {}         # id -> last store generation

        self.n_units = 0
        self.n_contexts = 0
        self.n_conns = 0
        self.n_packets = 0
        self.n_files = 0

    # ---------- helpers ----------
    def _unit(self, u):
        ns, pid, gen = u
        rec = self.units.get((ns, pid))
        if rec is None or rec['gen'] != gen:
            return None
        return rec

    def _conn(self, c):
        cid, gen = c
        rec = self.connections.get((cid, gen))
        if rec is None or rec['gen'] != gen:
            return None
        return rec

    def _step(self, epoch, state, col):
        if state == DENY:
            return DENY
        return self.images[epoch]['rows'][state][col]

    def _col(self, service):
        return self.label_to_col[self.name_to_label[service]]

    # ---------- operations ----------
    def op_stage(self, e):
        epoch = e['epoch']
        if epoch <= self.stage_hw:
            return REJECTED
        if len(self.images) >= self.limits['images']:
            return REJECTED
        try:
            rules, _atoms, _paths = parse_policy(e['policy'])
        except PolicyError:
            return REJECTED
        try:
            image, cells = compile_image(rules, self.name_to_label, self.ncols)
        except PolicyError:
            return REJECTED
        if self.cells_total + cells > self.limits['cells']:
            return REJECTED
        self.images[epoch] = {'accept': image['accept'], 'rows': image['rows'],
                              'cells': cells, 'refs': 0}
        self.stage_hw = epoch
        self.cells_total += cells
        return {'ok': True, 'epoch': epoch, 'image': image}

    def op_commit(self, e):
        epoch = e['epoch']
        if epoch not in self.images:
            return REJECTED
        self.active = epoch
        return OK

    def op_retire(self, e):
        epoch = e['epoch']
        img = self.images.get(epoch)
        if img is None or epoch == self.active or img['refs'] != 0:
            return REJECTED
        del self.images[epoch]
        self.cells_total -= img['cells']
        return OK

    def op_spawn(self, e):
        ns, pid, gen = e['unit']
        service = e['service']
        if service not in self.name_to_label:
            return REJECTED
        key = (ns, pid)
        if key in self.units or gen <= self.unit_hw.get(key, 0):
            return REJECTED
        if self.n_units >= self.limits['units']:
            return REJECTED
        self.units[key] = {'gen': gen, 'service': service, 'mark': 0, 'ctx': {}}
        self.unit_hw[key] = gen
        self.n_units += 1
        return OK

    def op_clone(self, e):
        parent = self._unit(e['parent'])
        if parent is None:
            return REJECTED
        ns, pid, gen = e['child']
        key = (ns, pid)
        if key in self.units or gen <= self.unit_hw.get(key, 0):
            return REJECTED
        if self.n_units >= self.limits['units']:
            return REJECTED
        ctx = dict(parent['ctx'])
        if self.n_contexts + len(ctx) > self.limits['contexts']:
            return REJECTED
        self.units[key] = {'gen': gen, 'service': parent['service'],
                           'mark': parent['mark'], 'ctx': ctx}
        self.unit_hw[key] = gen
        self.n_units += 1
        self.n_contexts += len(ctx)
        for epoch, _state in ctx.values():
            self.images[epoch]['refs'] += 1
        return OK

    def op_exit(self, e):
        unit = self._unit(e['unit'])
        if unit is None:
            return REJECTED
        ns, pid, _gen = e['unit']
        del self.units[(ns, pid)]
        self.n_units -= 1
        self.n_contexts -= len(unit['ctx'])
        for epoch, _state in unit['ctx'].values():
            self.images[epoch]['refs'] -= 1
        return OK

    def op_begin(self, e):
        if self.active is None:
            return REJECTED
        unit = self._unit(e['unit'])
        if unit is None:
            return REJECTED
        rid = e['rid']
        if rid <= unit['mark']:
            return REJECTED
        if self.n_contexts >= self.limits['contexts']:
            return REJECTED
        epoch = self.active
        img = self.images[epoch]
        state = img['rows'][0][self._col(unit['service'])]
        unit['ctx'][rid] = (epoch, state)
        unit['mark'] = rid
        self.n_contexts += 1
        img['refs'] += 1
        return {'ok': True, 'epoch': epoch, 'state': state}

    def op_finish(self, e):
        unit = self._unit(e['unit'])
        if unit is None:
            return REJECTED
        rid = e['rid']
        entry = unit['ctx'].get(rid)
        if entry is None:
            return REJECTED
        del unit['ctx'][rid]
        self.n_contexts -= 1
        epoch, state = entry
        img = self.images[epoch]
        img['refs'] -= 1
        allow = state != DENY and img['accept'][state]
        return {'ok': True, 'allow': bool(allow)}

    def op_open(self, e):
        cid, gen = e['connection']
        if (cid, gen) in self.connections or gen <= self.conn_hw.get(cid, 0):
            return REJECTED
        if self.n_conns >= self.limits['connections']:
            return REJECTED
        self.connections[(cid, gen)] = {'id': cid, 'gen': gen, 'mark': 0, 'pk': {}}
        self.conn_hw[cid] = gen
        self.n_conns += 1
        return OK

    def op_close(self, e):
        conn = self._conn(e['connection'])
        if conn is None:
            return REJECTED
        del self.connections[(conn['id'], conn['gen'])]
        self.n_conns -= 1
        self.n_packets -= len(conn['pk'])
        for packet in conn['pk'].values():
            self.images[packet['epoch']]['refs'] -= 1
        return OK

    def op_send(self, e):
        unit = self._unit(e['unit'])
        if unit is None:
            return REJECTED
        rid = e['rid']
        entry = unit['ctx'].get(rid)
        if entry is None:
            return REJECTED
        conn = self._conn(e['connection'])
        if conn is None:
            return REJECTED
        stream = e['stream']
        if stream <= conn['mark']:
            return REJECTED
        if self.n_packets >= self.limits['packets']:
            return REJECTED
        destination = e['destination']
        if destination not in self.name_to_label:
            return REJECTED
        epoch, state = entry
        cgen = conn['gen']
        wire = struct.pack('>4s5I', b'EMC4', epoch, state,
                           self.name_to_label[destination], stream, cgen)
        conn['pk'][stream] = {'epoch': epoch, 'state': state,
                              'dest': destination, 'wire': wire, 'recv': None}
        conn['mark'] = stream
        self.n_packets += 1
        self.images[epoch]['refs'] += 1
        return {'ok': True, 'wire': wire.hex()}

    def op_recv(self, e):
        conn = self._conn(e['connection'])
        if conn is None:
            return REJECTED
        packet = conn['pk'].get(e['stream'])
        if packet is None:
            return REJECTED
        wire = e['wire']
        if wire is not None:
            raw = _hex_valid(wire)
            if raw is None or raw != packet['wire']:
                return REJECTED
        rec = packet['recv']
        if rec is None:
            unit = self._unit(e['unit'])
            if unit is None:
                return REJECTED
            if unit['service'] != packet['dest']:
                return REJECTED
            rid = e['rid']
            if rid <= unit['mark']:
                return REJECTED
            if self.n_contexts >= self.limits['contexts']:
                return REJECTED
            epoch = packet['epoch']
            state = self._step(epoch, packet['state'], self._col(unit['service']))
            unit['ctx'][rid] = (epoch, state)
            unit['mark'] = rid
            self.n_contexts += 1
            self.images[epoch]['refs'] += 1
            packet['recv'] = (e['unit'], rid, epoch, state)
            return {'ok': True, 'epoch': epoch, 'state': state}
        # later delivery of the same packet
        ukey, rid_rec, epoch, state = rec
        if e['unit'] != ukey or e['rid'] != rid_rec:
            return REJECTED
        unit = self._unit(e['unit'])
        if unit is None or rid_rec not in unit['ctx']:
            return REJECTED
        return {'ok': True, 'epoch': epoch, 'state': state}

    def op_store(self, e):
        unit = self._unit(e['unit'])
        if unit is None:
            return REJECTED
        rid = e['rid']
        entry = unit['ctx'].get(rid)
        if entry is None:
            return REJECTED
        fid, fgen = e['file']
        epoch, state = entry
        cur = self.files.get(fid)
        if cur is None:
            if fgen <= self.file_hw.get(fid, 0):
                return REJECTED
            if self.n_files >= self.limits['files']:
                return REJECTED
            self.files[fid] = {'gen': fgen, 'epoch': epoch, 'state': state}
            self.file_hw[fid] = fgen
            self.n_files += 1
            self.images[epoch]['refs'] += 1
        else:
            if fgen != cur['gen']:
                return REJECTED
            old = cur['epoch']
            cur['epoch'] = epoch
            cur['state'] = state
            if old != epoch:
                self.images[old]['refs'] -= 1
                self.images[epoch]['refs'] += 1
        return OK

    def op_load(self, e):
        fid, fgen = e['file']
        cur = self.files.get(fid)
        if cur is None or cur['gen'] != fgen:
            return REJECTED
        unit = self._unit(e['unit'])
        if unit is None:
            return REJECTED
        rid = e['rid']
        if rid <= unit['mark']:
            return REJECTED
        if self.n_contexts >= self.limits['contexts']:
            return REJECTED
        epoch = cur['epoch']
        state = self._step(epoch, cur['state'], self._col(unit['service']))
        unit['ctx'][rid] = (epoch, state)
        unit['mark'] = rid
        self.n_contexts += 1
        self.images[epoch]['refs'] += 1
        return {'ok': True, 'epoch': epoch, 'state': state}

    def op_unlink(self, e):
        fid, fgen = e['file']
        cur = self.files.get(fid)
        if cur is None or cur['gen'] != fgen:
            return REJECTED
        del self.files[fid]
        self.n_files -= 1
        self.images[cur['epoch']]['refs'] -= 1
        return OK

    def op_inspect(self, _e=None):
        entries = []
        for epoch in sorted(self.images):
            img = self.images[epoch]
            entries.append([epoch, len(img['rows']), img['cells'], img['refs']])
        return {'ok': True, 'active': self.active, 'images': entries,
                'units': self.n_units, 'contexts': self.n_contexts,
                'connections': self.n_conns, 'packets': self.n_packets,
                'files': self.n_files}

    def event(self, e):
        op = e['op']
        if op == 'stage':
            return self.op_stage(e)
        if op == 'commit':
            return self.op_commit(e)
        if op == 'retire':
            return self.op_retire(e)
        if op == 'spawn':
            return self.op_spawn(e)
        if op == 'clone':
            return self.op_clone(e)
        if op == 'exit':
            return self.op_exit(e)
        if op == 'begin':
            return self.op_begin(e)
        if op == 'finish':
            return self.op_finish(e)
        if op == 'open':
            return self.op_open(e)
        if op == 'close':
            return self.op_close(e)
        if op == 'send':
            return self.op_send(e)
        if op == 'recv':
            return self.op_recv(e)
        if op == 'store':
            return self.op_store(e)
        if op == 'load':
            return self.op_load(e)
        if op == 'unlink':
            return self.op_unlink(e)
        return self.op_inspect()
